                for (int d = 0; d < 8; d++) { int nx = x + dx[d], ny = y + dy[d], lx = nx - left, ly = ny - top; if (lx < 0 || ly < 0 || lx >= 33 || ly >= 33 || !ShelterWalkable(nx, ny) || (walkOnly && !map.CanWalk(nx,ny)) || (confinedRoom != null && !confinedRoom.Contains(Key(nx,ny)))) continue; int next = ly * 33 + lx; if (shelterSeen[next] || !occupancy.Allows(Key(nx, ny), Species.Human) || ZombieAt(nx, ny)) continue; bool diagonal = nx != x && ny != y; if (diagonal && (IsDoor(x, y) || IsDoor(nx, ny) || !map.CanWalk(nx, y) || !map.CanWalk(x, ny) || (confinedRoom != null && (!confinedRoom.Contains(Key(nx,y)) || !confinedRoom.Contains(Key(x,ny)))))) continue; ActorState candidate = actor; candidate.x = nx; candidate.y = ny; bool safe = true; for (int j = 0; j < threats; j++) if ((foodRoute && SafeFoodTargets && Math.Max(Math.Abs(nx-escapeThreats[j].x),Math.Abs(ny-escapeThreats[j].y))<=2) || DistanceSquared(candidate, escapeThreats[j]) < (actor.turnAtTick > Tick ? DistanceSquared(actor, escapeThreats[j]) : Math.Min(4, DistanceSquared(actor, escapeThreats[j])))) { safe = false; break; } if (!safe) continue; shelterSeen[next] = true; shelterSteps[next] = shelterSteps[cell] + 1; shelterFirst[next] = cell == start ? d : shelterFirst[cell]; shelterQueue[tail++] = next; } // Avoid observed threats and diagonal doorway/corner shortcuts throughout the path.
