            actor.shelterState = room.Contains(Key(actor.x, actor.y)) ? ShelterState.Inside : ShelterState.Seeking; if ((!HungerEnabled || !HungryDepartureAllowed(actor, room, threatIndex)) && DoorBracing && TryBraceDoor(index, ref actor, room, threatIndex)) return true; if ((!HungerEnabled || actor.hunger < HungerRules.SeekAt) && DoorRepair && TryRepairDoor(index, ref actor, room, threatIndex)) return true; if (RestHealing && TryRestInShelter(index, ref actor, room, threatIndex)) return true; if (ShelterRecovery && actor.foodExploreRoomId==0 && TryShelterDeparture(index, ref actor, room, threatIndex, out direction)) return true; CloseNearbyDoors(actor, room); bool returningFood = (FoodTripRetreat && actor.homeShelterId==room.id && actor.shelterState==ShelterState.Seeking) || (FoodExploration && actor.foodExploreRoomId==room.id); int length; direction = ShelterRoute(actor, actor.shelterX, actor.shelterY, threats, out length, foodRoute:returningFood); if (direction < 0) { int alternate = PickShelterCell(room, actor); if (alternate >= 0 && (alternate % Width != actor.shelterX || alternate / Width != actor.shelterY)) { actor.shelterX = alternate % Width; actor.shelterY = alternate / Width; direction = ShelterRoute(actor, actor.shelterX, actor.shelterY, threats, out length, foodRoute:returningFood); } if (direction < 0) { if (threatIndex < 0 || DistanceSquared(actor, actors[threatIndex]) >= 16) { direction = 8; actors[index] = actor; return true; } RejectShelter(ref actor, room.id); actors[index] = actor; return false; } } actors[index] = actor; if (direction != 8) { int x = actor.x + dx[direction], y = actor.y + dy[direction]; if (map.Get(x, y) == Terrain.DoorClosed) { SetDoor(x, y, true); direction = 8; } } return true; // Opening consumes the opportunity; entry and safe closing follow on later ticks.
